def resolve(path, cwd, links):
    if not isinstance(path, str) or not isinstance(cwd, str) or not isinstance(links, dict):
        return None

    if not cwd.startswith('/') or (cwd != '/' and cwd.endswith('/')):
        return None

    link_count = 0
    max_links = 8

    if path.startswith('/'):
        current = '/'
        components = path[1:].split('/')
    else:
        current = cwd
        components = path.split('/')

    i = 0
    while i < len(components):
        comp = components[i]

        if comp == '' or comp == '.':
            i += 1
            continue

        if comp == '..':
            if current != '/':
                current = current.rsplit('/', 1)[0]
                if current == '':
                    current = '/'
            i += 1
            continue

        if current == '/':
            next_path = '/' + comp
        else:
            next_path = current + '/' + comp

        if next_path in links:
            link_count += 1
            if link_count > max_links:
                return None

            target = links[next_path]

            if target.startswith('/'):
                current = '/'
                new_components = target[1:].split('/')
            else:
                if current == '/':
                    current = '/'
                new_components = target.split('/')

